<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Mockup — Solopreneur · Summary (/solopreneur)</title>
  <link rel="icon" href="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24'%3E%3Crect width='24' height='24' rx='7' fill='%23c2009b'/%3E%3Cpath d='M12 5l1.6 4.4L18 11l-4.4 1.6L12 17l-1.6-4.4L6 11l4.4-1.6z' fill='%23fff'/%3E%3C/svg%3E" />
  <style>
    /* ============================================================
       1. DESIGN TOKENS — solopreneur surface (light variant)
       ============================================================ */
    *, *::before, *::after { box-sizing: border-box; }

    :root {
      --bg: #f5f5f6;
      --card: #ffffff;
      --line: #ececef;
      --line-soft: #f2f2f4;
      --ink: #111114;
      --ink-2: #5f5f68;
      --ink-3: #95959e;
      --accent: #c2009b;
      --accent-2: #d6008f;
      --accent-ink: #a30080;
      --accent-soft: #fbe9f6;
      --green: #0b7d4e;
      --green-soft: #e6f6ee;
      --danger: #c02626;
      --black: #0c0c0e;
      --r-sm: 8px; --r-md: 12px; --r-lg: 14px; --r-xl: 16px; --r-pill: 999px;
      --shadow: 0 1px 2px rgba(17, 17, 20, .04), 0 12px 28px rgba(17, 17, 20, .045);
      --fast: 150ms; --base: 220ms;
      --ease: cubic-bezier(.4, 0, .2, 1);
      --sidebar: 332px;
    }

    html, body { height: 100%; }
    body {
      margin: 0;
      font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
      background: var(--card);
      color: var(--ink);
      -webkit-font-smoothing: antialiased;
    }
    button { font: inherit; cursor: pointer; color: inherit; }
    a { color: inherit; text-decoration: none; }
    :focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; border-radius: 6px; }
    .sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0; }

    /* ============================================================
       2. SHELL
       ============================================================ */
    .app { display: grid; grid-template-columns: var(--sidebar) minmax(0, 1fr); min-height: 100vh; background: var(--card); }
    .main { display: flex; flex-direction: column; min-width: 0; background: var(--bg); }

    /* --- sidebar --- */
    .sidebar {
      background: var(--card);
      border-right: 1px solid var(--line);
      padding: 26px 22px 20px;
      display: flex;
      flex-direction: column;
      gap: 26px;
      position: sticky;
      top: 0;
      height: 100vh;
    }
    .brand { display: flex; align-items: center; gap: 12px; padding: 0 6px; }
    .brand-mark { width: 34px; height: 34px; border-radius: 10px; background: var(--accent); color: #fff; display: grid; place-items: center; }
    .brand-name { font-size: 19px; font-weight: 700; letter-spacing: -.3px; }
    .brand-name span { color: var(--accent); }

    .side-user { display: flex; align-items: center; gap: 14px; padding: 0 6px; }
    .avatar {
      width: 46px; height: 46px; border-radius: 50%; flex: 0 0 auto;
      display: grid; place-items: center;
      font-size: 15px; font-weight: 600; color: #fff;
      background: linear-gradient(145deg, #d0009f, #6f0057);
    }
    .side-user-txt { display: flex; flex-direction: column; min-width: 0; }
    .side-user-txt strong { font-size: 15px; font-weight: 650; }
    .side-user-txt small { font-size: 13px; color: var(--ink-2); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }

    .nav { display: flex; flex-direction: column; gap: 2px; }
    .nav a {
      display: flex; align-items: center; gap: 14px;
      padding: 10px 12px; border-radius: var(--r-md);
      font-size: 15px; font-weight: 500; color: var(--ink);
      transition: background var(--fast) var(--ease);
    }
    .nav a:hover { background: #f7f7f8; }
    .nav a[aria-current="page"] { font-weight: 650; background: #fbf7fa; }
    .dot { width: 8px; height: 8px; border-radius: 50%; flex: 0 0 auto; background: var(--ink-3); }
    .nav .dot { margin-left: 4px; background: #8d1158; opacity: .8; }
    .nav a[aria-current="page"] .dot { background: var(--accent); opacity: 1; }
    .dot-pink { background: var(--accent) !important; }
    .dot-green { background: var(--green) !important; }

    .side-foot { margin-top: auto; display: flex; flex-direction: column; gap: 12px; }
    .logout {
      display: flex; align-items: center; gap: 14px;
      background: none; border: 0; padding: 10px 12px; border-radius: var(--r-md);
      font-size: 15px; font-weight: 600; color: var(--ink);
    }
    .logout:hover { background: #f7f7f8; }
    .made { margin: 0 0 0 12px; font-size: 12.5px; color: var(--ink-3); }
    .made button { background: none; border: 0; padding: 0; color: var(--ink-3); text-decoration: underline; font-size: 12.5px; }
    .made button:hover { color: var(--accent); }

    /* --- topbar --- */
    .topbar {
      position: sticky; top: 0; z-index: 20;
      display: flex; align-items: center; gap: 20px;
      padding: 20px 32px;
      background: var(--card);
      border-bottom: 1px solid var(--line);
    }
    .greeting h1 { margin: 0 0 4px; font-size: 21px; font-weight: 700; letter-spacing: -.3px; }
    .greeting p { margin: 0; font-size: 14.5px; color: var(--ink-2); }
    .topbar-actions { margin-left: auto; display: flex; align-items: center; gap: 12px; }

    .search { position: relative; }
    .search-input {
      width: 264px; height: 42px; border-radius: var(--r-pill);
      border: 1px solid var(--line); background: var(--card);
      padding: 0 18px; font-size: 14.5px; font-family: inherit; color: var(--ink);
    }
    .search-input::placeholder { color: var(--ink-3); }
    .search-input:focus { outline: none; border-color: var(--accent); box-shadow: 0 0 0 3px rgba(194, 0, 155, .12); }
    .search-results {
      position: absolute; top: 48px; right: 0; width: 340px;
      background: var(--card); border: 1px solid var(--line); border-radius: var(--r-md);
      box-shadow: var(--shadow); padding: 8px; z-index: 40;
    }
    .search-results button { display: block; width: 100%; text-align: left; background: none; border: 0; padding: 9px 10px; border-radius: var(--r-sm); font-size: 14px; }
    .search-results button:hover { background: #f7f7f8; }
    .search-results small { display: block; font-size: 12px; color: var(--ink-3); }
    .search-results .none { padding: 10px; font-size: 13.5px; color: var(--ink-3); }

    .lang { position: relative; }
    .lang-btn {
      display: inline-flex; align-items: center; gap: 8px;
      height: 42px; padding: 0 16px; border-radius: var(--r-pill);
      border: 1px solid var(--line); background: var(--card);
      font-size: 14.5px; font-weight: 600;
    }
    .lang-btn:hover { background: #fafafa; }
    .lang-menu {
      position: absolute; top: 48px; right: 0; width: 160px; z-index: 40;
      background: var(--card); border: 1px solid var(--line); border-radius: var(--r-md);
      box-shadow: var(--shadow); padding: 6px;
    }
    .lang-menu button { display: block; width: 100%; text-align: left; background: none; border: 0; padding: 9px 10px; border-radius: var(--r-sm); font-size: 14px; }
    .lang-menu button:hover { background: #f7f7f8; }
    .lang-menu button[aria-current="true"] { color: var(--accent-ink); font-weight: 650; }

    /* --- buttons --- */
    .btn {
      height: 42px; padding: 0 20px; border-radius: var(--r-pill);
      border: 1px solid transparent; font-size: 14.5px; font-weight: 600;
      display: inline-flex; align-items: center; justify-content: center; gap: 8px;
      transition: transform var(--fast) var(--ease), background var(--fast) var(--ease);
    }
    .btn:active { transform: scale(.985); }
    .btn-dark { background: var(--black); color: #fff; }
    .btn-dark:hover { background: #222227; }
    .btn-ghost-pill { background: var(--card); border-color: #e3e3e7; color: var(--ink); }
    .btn-ghost-pill:hover { background: #f7f7f8; }
    .btn-pink { background: var(--accent-2); color: #fff; }
    .btn-pink:hover { background: #c1007f; }
    .btn-sm { height: 34px; padding: 0 14px; font-size: 13.5px; }
    .btn[disabled] { opacity: .45; cursor: not-allowed; }

    /* ============================================================
       3. CONTENT / GRID
       ============================================================ */
    .content { padding: 26px 32px 56px; }
    .layout { display: grid; grid-template-columns: minmax(0, 1fr) 400px; gap: 24px; align-items: start; }
    .layout.one { grid-template-columns: minmax(0, 940px); }
    .col-left { display: flex; flex-direction: column; gap: 24px; min-width: 0; }
    .col-right { position: sticky; top: 104px; display: flex; flex-direction: column; gap: 24px; }
    .row-2 { display: grid; grid-template-columns: 1fr 1fr; gap: 24px; min-width: 0; }

    .card {
      background: var(--card);
      border: 1px solid var(--line);
      border-radius: var(--r-xl);
      box-shadow: var(--shadow);
      padding: 26px 28px;
      min-width: 0;
    }
    .card-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 16px; }
    .card h2 { margin: 0; font-size: 17px; font-weight: 700; letter-spacing: -.2px; }
    .card-desc { margin: 8px 0 0; font-size: 14.5px; line-height: 1.5; color: var(--ink-2); max-width: 54ch; }
    .link-accent { background: none; border: 0; padding: 0; font-size: 14.5px; font-weight: 650; color: var(--accent); white-space: nowrap; }
    .link-accent:hover { text-decoration: underline; }

    /* key / value rows */
    .kv { margin: 22px 0 0; display: flex; flex-direction: column; gap: 16px; }
    .kv-row { display: flex; justify-content: space-between; gap: 18px; font-size: 15px; }
    .kv-row dt { margin: 0; color: var(--ink-2); }
    .kv-row dd { margin: 0; font-weight: 600; text-align: right; }

    /* wallet */
    .credits { display: flex; align-items: baseline; gap: 10px; margin: 16px 0 4px; }
    .credits strong { font-size: 40px; font-weight: 700; letter-spacing: -1.2px; }
    .credits span { font-size: 15px; font-weight: 600; }
    .tiny { margin: 14px 0 0; font-size: 12.5px; color: var(--ink-3); }
    .card-actions { display: flex; gap: 12px; margin-top: 20px; flex-wrap: wrap; }

    /* at a glance */
    .glance { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 16px; margin-top: 20px; }
    .glance-item { background: #f7f7f8; border-radius: var(--r-md); padding: 18px 18px 16px; display: flex; flex-direction: column; gap: 6px; }
    .glance-item strong { font-size: 27px; font-weight: 700; letter-spacing: -.8px; }
    .glance-item span { font-size: 13.5px; color: var(--ink-2); }
    .bar { height: 4px; border-radius: var(--r-pill); background: #e6e6ea; overflow: hidden; margin-top: 10px; }
    .bar i { display: block; height: 100%; border-radius: var(--r-pill); background: var(--accent-2); }
    .bar-light { background: rgba(255, 255, 255, .32); }
    .bar-light i { background: #fff; }

    /* projects tiles */
    .projects { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 18px; margin-top: 22px; }
    .tile {
      border: 0; text-align: left; color: #fff;
      border-radius: var(--r-lg); padding: 20px; min-height: 196px;
      display: flex; flex-direction: column; justify-content: space-between;
      transition: transform var(--fast) var(--ease), filter var(--fast) var(--ease);
    }
    .tile:hover { transform: translateY(-2px); filter: brightness(1.04); }
    .tile h3 { margin: 0; font-size: 15.5px; font-weight: 600; }
    .tile header span { font-size: 13px; color: rgba(255, 255, 255, .82); }
    .tile strong { display: block; font-size: 26px; font-weight: 700; margin-bottom: 12px; letter-spacing: -.6px; }
    .tile small { font-size: 12.5px; color: rgba(255, 255, 255, .85); }
    .tile.g1 { background: linear-gradient(145deg, #cb009f 0%, #b8008f 45%, #8d0072 100%); }
    .tile.g2 { background: radial-gradient(120% 120% at 0% 100%, #a3008c 0%, #5c0a55 45%, #2c0728 100%); }
    .tile.g3 { background: radial-gradient(120% 130% at 10% 100%, #6c1470 0%, #2b0a2f 45%, #0d0a10 100%); }

    /* tasks */
    .tasks { list-style: none; margin: 20px 0 0; padding: 0; display: flex; flex-direction: column; gap: 22px; }
    .task { display: flex; gap: 12px; }
    .task > .dot { margin-top: 7px; }
    .task-title { background: none; border: 0; padding: 0; font-size: 15.5px; font-weight: 650; text-align: left; color: var(--ink); }
    .task-title:hover { color: var(--accent-ink); }
    .task-meta { margin: 4px 0 0; font-size: 12.5px; color: var(--ink-2); }
    .task-status { margin: 6px 0 0; font-size: 12px; font-weight: 700; }
    .st-pink { color: var(--accent); }
    .st-green { color: var(--green); }
    .is-done .task-title { color: var(--ink-3); text-decoration: line-through; }
    .is-done .task-meta { color: var(--ink-3); }

    /* updates */
    .updates { list-style: none; margin: 18px 0 0; padding: 0; display: flex; flex-direction: column; gap: 22px; }
    .update { display: flex; gap: 12px; }
    .update > .dot { margin-top: 7px; }
    .update h4 { margin: 0; font-size: 15.5px; font-weight: 650; display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
    .update p { margin: 6px 0 0; font-size: 14px; line-height: 1.5; color: var(--ink-2); }
    .update time { display: block; margin-top: 6px; font-size: 12px; color: var(--ink-3); }
    .pill { font-size: 11.5px; font-weight: 600; padding: 2px 9px; border-radius: var(--r-pill); }
    .pill-green { color: var(--green); background: var(--green-soft); }
    .pill-pink { color: var(--accent-ink); background: var(--accent-soft); }

    /* chat */
    .online { display: inline-flex; align-items: center; gap: 8px; font-size: 12.5px; font-weight: 600; color: var(--green); white-space: nowrap; }
    .online .dot { background: var(--green); }
    .thread { display: flex; flex-direction: column; gap: 18px; margin: 18px 0 0; max-height: 460px; overflow-y: auto; padding-right: 4px; }
    .chat-card.full .thread { max-height: none; min-height: 420px; }
    .msg { display: flex; gap: 12px; align-items: flex-start; }
    .msg-me { justify-content: flex-end; }
    .avatar-sm { width: 38px; height: 38px; border-radius: 50%; display: grid; place-items: center; font-size: 13px; font-weight: 600; color: #fff; flex: 0 0 auto; }
    .avatar-ai { background: linear-gradient(145deg, #c2009b, #8a006f); }
    .msg-body { display: flex; flex-direction: column; gap: 6px; max-width: min(620px, 78%); }
    .msg-me .msg-body { align-items: flex-end; }
    .msg-who { font-size: 11px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: var(--ink-3); }
    .bubble { background: #f5f5f6; border-radius: var(--r-lg); padding: 12px 16px; font-size: 14.5px; line-height: 1.5; }
    .bubble-me { background: var(--black); color: #fff; }
    .msg time { font-size: 11.5px; color: var(--ink-3); }
    .typing { display: inline-flex; gap: 4px; align-items: center; }
    .typing i { width: 6px; height: 6px; border-radius: 50%; background: var(--ink-3); animation: blink 1.1s infinite; }
    .typing i:nth-child(2) { animation-delay: .15s; }
    .typing i:nth-child(3) { animation-delay: .3s; }
    @keyframes blink { 0%, 100% { opacity: .25; } 50% { opacity: 1; } }

    .composer { display: flex; gap: 12px; margin-top: 18px; }
    .composer input {
      flex: 1; height: 48px; border-radius: var(--r-pill);
      border: 1px solid #e3e3e7; padding: 0 20px;
      font-size: 14.5px; font-family: inherit; color: var(--ink); background: var(--card);
    }
    .composer input:focus { outline: none; border-color: var(--accent); box-shadow: 0 0 0 3px rgba(194, 0, 155, .12); }
    .composer .btn { height: 48px; padding: 0 26px; }

    /* calendar */
    .cal-group { margin-bottom: 22px; }
    .cal-group:last-child { margin-bottom: 0; }
    .cal-group h3 { margin: 0 0 14px; font-size: 11.5px; letter-spacing: .09em; font-weight: 700; color: var(--ink-3); }
    .cal-list { border-left: 1px solid var(--line); padding-left: 16px; display: flex; flex-direction: column; gap: 16px; }
    .cal-event { display: flex; flex-direction: column; gap: 2px; width: 100%; text-align: left; background: none; border: 0; padding: 0; }
    .cal-event:hover .cal-title { color: var(--accent-ink); }
    .cal-time { font-size: 14px; font-weight: 600; }
    .cal-title { font-size: 15px; font-weight: 650; }
    .cal-meta { font-size: 12.5px; color: var(--ink-2); }

    /* tables */
    .table { width: 100%; border-collapse: collapse; font-size: 14px; margin-top: 16px; }
    .table th { text-align: left; font-size: 11.5px; letter-spacing: .07em; text-transform: uppercase; color: var(--ink-3); padding: 0 0 10px; font-weight: 700; }
    .table td { padding: 12px 0; border-top: 1px solid var(--line-soft); }
    .table td:last-child, .table th:last-child { text-align: right; }

    /* toolbar / chips */
    .toolbar { display: flex; gap: 12px; margin-top: 18px; flex-wrap: wrap; }
    .toolbar .input { max-width: 320px; }
    .toolbar select.input { max-width: 220px; }
    .chips { display: flex; gap: 8px; margin-top: 18px; flex-wrap: wrap; }
    .chip { height: 34px; padding: 0 14px; border-radius: var(--r-pill); border: 1px solid #e6e6ea; background: var(--card); font-size: 13.5px; font-weight: 600; color: var(--ink-2); }
    .chip.is-on { background: var(--black); border-color: var(--black); color: #fff; }

    .rows { display: flex; flex-direction: column; gap: 12px; margin-top: 18px; }
    .row-item { border: 1px solid var(--line); border-radius: var(--r-md); padding: 16px 18px; background: var(--card); }
    .row-item.is-open { border-color: #e0d5dd; background: #fdfbfd; }
    .row-head { display: flex; align-items: center; gap: 16px; width: 100%; background: none; border: 0; padding: 0; text-align: left; }
    .row-head h3 { margin: 0; font-size: 15.5px; font-weight: 650; }
    .row-head small { display: block; font-size: 12.5px; color: var(--ink-2); margin-top: 2px; }
    .row-head .bar { width: 180px; margin: 0; }
    .row-head .pct { font-size: 14px; font-weight: 650; width: 44px; text-align: right; }
    .row-detail { margin-top: 16px; padding-top: 16px; border-top: 1px dashed var(--line); }

    /* forms */
    .form { margin-top: 20px; display: flex; flex-direction: column; gap: 16px; max-width: 560px; }
    .form-row { display: flex; justify-content: space-between; align-items: center; gap: 16px; font-size: 15px; color: var(--ink-2); }
    .form-row .value { font-weight: 600; color: var(--ink); }
    .form-actions { display: flex; gap: 12px; margin-top: 6px; flex-wrap: wrap; }
    .field { display: flex; flex-direction: column; gap: 6px; }
    .field label { font-size: 13px; font-weight: 600; color: var(--ink-2); }
    .input {
      width: 100%; height: 44px; border-radius: var(--r-md);
      border: 1px solid #e3e3e7; padding: 0 14px;
      font-size: 14.5px; font-family: inherit; color: var(--ink); background: var(--card);
    }
    .input:focus { outline: none; border-color: var(--accent); box-shadow: 0 0 0 3px rgba(194, 0, 155, .12); }
    .field .err { font-size: 12.5px; color: var(--danger); }
