    .skeleton { border: 1px solid var(--line); border-radius: var(--r-xl); background: linear-gradient(90deg, #f2f2f4 25%, #f9f9fa 37%, #f2f2f4 63%); background-size: 400% 100%; animation: shimmer 1.4s ease-in-out infinite; }
    @keyframes shimmer { 0% { background-position: 100% 0; } 100% { background-position: 0 0; } }
    .state-card { text-align: center; }

    /* modals */
    .backdrop { position: fixed; inset: 0; z-index: 100; background: rgba(12, 12, 14, .42); }
    .dialog {
      position: fixed; z-index: 101; top: 50%; left: 50%; transform: translate(-50%, -50%);
      width: min(520px, calc(100vw - 32px)); max-height: calc(100vh - 64px); overflow: auto;
      background: var(--card); border-radius: 18px; padding: 26px;
      box-shadow: 0 24px 64px rgba(12, 12, 14, .28);
    }
    .dialog h2 { margin: 0 0 6px; font-size: 19px; font-weight: 700; }
    .dialog p.sub { margin: 0 0 18px; font-size: 14px; color: var(--ink-2); }
    .dialog-foot { display: flex; gap: 12px; justify-content: flex-end; margin-top: 22px; flex-wrap: wrap; }
    .radio { display: flex; align-items: center; gap: 12px; padding: 14px; border: 1px solid #e6e6ea; border-radius: var(--r-md); cursor: pointer; margin-bottom: 10px; }
    .radio:has(input:checked) { border-color: var(--accent); background: #fdf3fa; }
    .radio span { display: flex; flex-direction: column; font-size: 14.5px; }
    .radio span small { font-size: 12.5px; color: var(--ink-2); }

    /* toasts */
    .toasts { position: fixed; right: 24px; bottom: 88px; z-index: 200; display: flex; flex-direction: column; gap: 10px; }
    .toast { background: var(--black); color: #fff; font-size: 14px; padding: 12px 18px; border-radius: var(--r-md); box-shadow: 0 12px 32px rgba(0, 0, 0, .28); animation: slide-in var(--base) var(--ease); }
    .toast-error { background: var(--danger); }
    .toast.out { opacity: 0; transform: translateY(6px); transition: opacity 200ms var(--ease), transform 200ms var(--ease); }
    @keyframes slide-in { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: none; } }

    /* dev panel (mock scaffolding) */
    .dev { position: fixed; right: 24px; bottom: 24px; z-index: 300; font-size: 12.5px; }
    .dev-btn { background: var(--black); color: #fff; border: 0; border-radius: var(--r-pill); padding: 8px 14px; opacity: .35; }
    .dev:hover .dev-btn, .dev-btn:focus-visible { opacity: 1; }
    .dev-body {
      position: absolute; right: 0; bottom: 46px; width: 248px;
      background: var(--card); border: 1px solid var(--line); border-radius: var(--r-md);
      box-shadow: var(--shadow); padding: 14px; display: flex; flex-direction: column; gap: 10px;
    }
    .dev-body label { display: flex; align-items: center; gap: 8px; }

    /* ============================================================
       4. RESPONSIVE
       ============================================================ */
    @media (max-width: 1440px) {
      .layout { grid-template-columns: minmax(0, 1fr) 340px; }
    }
    @media (max-width: 1180px) {
      .layout { grid-template-columns: minmax(0, 1fr); }
      .col-right { position: static; }
      .glance { grid-template-columns: repeat(2, minmax(0, 1fr)); }
      .row-2 { grid-template-columns: 1fr; }
    }
    @media (max-width: 980px) {
      .app { grid-template-columns: 1fr; }
      .sidebar {
        position: sticky; height: auto; z-index: 30;
        flex-direction: row; align-items: center; gap: 14px;
        padding: 12px 16px; overflow-x: auto;
        border-right: 0; border-bottom: 1px solid var(--line);
      }
      .side-user-txt, .brand-name, .made { display: none; }
      .nav { flex-direction: row; gap: 4px; }
      .nav a { padding: 8px 10px; white-space: nowrap; }
      .side-foot { margin: 0; }
      .logout span { display: none; }
      .topbar { flex-wrap: wrap; padding: 16px; }
      .topbar-actions { width: 100%; justify-content: flex-end; }
      .search-input { width: 160px; }
      .content { padding: 16px; }
      .projects { grid-template-columns: 1fr; }
      .glance { grid-template-columns: 1fr 1fr; }
      .card { padding: 20px; }
    }
    @media (max-width: 560px) {
      .glance { grid-template-columns: 1fr; }
      .row-head .bar { display: none; }
      .dialog { padding: 20px; }
    }

    @media (prefers-reduced-motion: reduce) {
      *, *::before, *::after { transition: none !important; animation: none !important; }
