  /* ==============================================================
     D. HELPERS
     ============================================================== */
  const $ = (id) => document.getElementById(id);

  function esc(value) {
    return String(value == null ? '' : value).replace(/[&<>"']/g, (c) => (
      { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]
    ));
  }
  function t(key) {
    return (I18N[state.lang] && I18N[state.lang][key]) || I18N.EN[key] || key;
  }
  const money = (n) => '€' + Number(n).toFixed(2);

  function shortDate(iso) {
    const d = new Date(iso + 'T00:00:00');
    return new Intl.DateTimeFormat(LANG_LOCALE[state.lang], { day: 'numeric', month: 'short', year: 'numeric' }).format(d);
  }
  function dateLine() {
    const fmt = new Intl.DateTimeFormat(LANG_LOCALE[state.lang], {
      weekday: 'long', day: 'numeric', month: 'long', year: 'numeric'
    });
    let text = fmt.format(CLOCK);
    if (text.indexOf(',') === -1) {
      const i = text.indexOf(' ');
      text = text.slice(0, i) + ',' + text.slice(i);
    }
    return t('todayIs') + ' ' + text;
  }
  function nowTime() {
    const d = new Date();
    return String(d.getHours()).padStart(2, '0') + ':' + String(d.getMinutes()).padStart(2, '0');
  }

  const ICONS = {
    spark: '<svg viewBox="0 0 24 24" width="18" height="18" fill="currentColor" aria-hidden="true"><path d="M12 2.6l1.9 5.7 5.7 1.9-5.7 1.9L12 17.8l-1.9-5.7L4.4 10.2l5.7-1.9z"/></svg>',
    globe: '<svg viewBox="0 0 24 24" width="17" height="17" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3c2.5 2.5 3.8 5.6 3.8 9s-1.3 6.5-3.8 9c-2.5-2.5-3.8-5.6-3.8-9S9.5 5.5 12 3z"/></svg>',
    chevron: '<svg viewBox="0 0 24 24" width="15" height="15" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="M6 9l6 6 6-6"/></svg>',
    logout: '<svg viewBox="0 0 24 24" width="19" height="19" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M15 4h3a2 2 0 012 2v12a2 2 0 01-2 2h-3"/><path d="M10 8l-4 4 4 4M6 12h9"/></svg>'
  };

  /* ==============================================================
     E. MOCK SERVER — routes + fetch interception
     ============================================================== */
  const json = (data, status) => new Response(JSON.stringify(data), {
    status: status || 200,
    headers: { 'Content-Type': 'application/json' }
  });
  function parseBody(init) {
    try { return JSON.parse(init.body); } catch (e) { return {}; }
  }
  const empty = () => state.dev.empty;

  function summaryPayload() {
    const d = state.data;
    return {
      user: d.user,
      wallet: d.wallet,
      stats: d.stats,
      projects: empty() ? [] : d.projects,
      tasks: empty() ? [] : d.tasks,
      updates: empty() ? [] : d.updates,
      events: empty() ? [] : d.events,
      messages: empty() ? [] : d.messages
    };
  }

  const serverRoutes = [
    { method: 'GET', path: /^\/api\/solopreneur\/summary$/, handler: () => summaryPayload() },
    { method: 'GET', path: /^\/api\/solopreneur\/account$/, handler: () => ({ user: state.data.user }) },
    {
      method: 'PATCH', path: /^\/api\/solopreneur\/account$/, handler: ({ body }) => {
        Object.assign(state.data.user, body);
        return { user: state.data.user };
      }
    },
    {
      method: 'GET', path: /^\/api\/solopreneur\/projects$/, handler: () => ({
        projects: empty() ? [] : state.data.projects
      })
    },
    {
      method: 'POST', path: /^\/api\/solopreneur\/projects$/, handler: ({ body }) => {
        const name = String(body.name || '').trim();
        if (!name) throw new Error('invalid_name');
        const variants = ['g1', 'g2', 'g3'];
        const project = {
          id: 'p_' + Date.now(),
          name,
          tasks: Math.max(0, Math.min(50, Number(body.tasks) || 0)),
          progress: 0,
          variant: variants[state.data.projects.length % 3],
          updated: '2026-10-19'
        };
        state.data.projects.unshift(project);
        return { projects: state.data.projects, project };
      }
    },
    {
      method: 'GET', path: /^\/api\/solopreneur\/wallet$/, handler: () => ({
        wallet: state.data.wallet,
        invoices: empty() ? [] : state.data.invoices
      })
    },
    {
      method: 'POST', path: /^\/api\/solopreneur\/wallet\/credits$/, handler: ({ body }) => {
        const pack = CREDIT_PACKS.find((p) => p.id === body.pack) || CREDIT_PACKS[0];
        const w = state.data.wallet;
        w.credits += pack.credits;
        state.data.invoices.unshift({
          id: 'i_' + Date.now(), date: '19 Oct 2026',
          desc: pack.credits + ' cxj credits', amount: pack.price, status: 'Paid'
        });
        return { wallet: w, invoices: state.data.invoices };
      }
    },
    {
      method: 'PATCH', path: /^\/api\/solopreneur\/wallet\/plan$/, handler: ({ body }) => {
        const plan = PLANS.find((p) => p.id === body.plan) || PLANS[0];
        state.data.wallet.plan = plan.name;
        state.data.wallet.invoice = plan.price;
        state.data.user.plan = plan.name;
        return { wallet: state.data.wallet, user: state.data.user };
      }
    },
    {
      method: 'GET', path: /^\/api\/solopreneur\/updates$/, handler: () => ({
        updates: empty() ? [] : state.data.updates
      })
    },
    {
      method: 'POST', path: /^\/api\/solopreneur\/updates\/read$/, handler: () => {
        state.data.updates.forEach((u) => { u.read = true; });
        return { updates: state.data.updates };
      }
    },
    {
      method: 'GET', path: /^\/api\/solopreneur\/messages$/, handler: () => ({
        messages: empty() ? [] : state.data.messages
      })
    },
    {
      method: 'POST', path: /^\/api\/solopreneur\/messages$/, handler: ({ body }) => {
        const text = String(body.text || '').trim();
        if (!text) throw new Error('empty_message');
        state.data.messages.push({ id: 'm_' + Date.now(), from: 'me', text, time: nowTime() });
        return { messages: state.data.messages };
      }
    },
    {
      method: 'POST', path: /^\/api\/solopreneur\/tasks\/([^/]+)\/(complete|reopen)$/,
      handler: ({ params }) => {
        const id = params[0];
        const op = params[1];
        const task = state.data.tasks.find((x) => x.id === id);
        if (!task) throw new Error('task_not_found');
        task.status = op === 'complete' ? 'done' : 'in_progress';
        const project = state.data.projects.find((p) => p.name === task.context);
        if (project) {
          project.progress = Math.max(0, Math.min(100, project.progress + (op === 'complete' ? 3 : -3)));
        }
        state.data.stats.tasks = Math.max(0, state.data.stats.tasks + (op === 'complete' ? 1 : -1));
        return { tasks: state.data.tasks, projects: state.data.projects, stats: state.data.stats };
      }
    }
  ];

  // MOCK: latency + failure injection, keeps the real fetch contract
  function mockFetch(input, init) {
    init = init || {};
    const url = typeof input === 'string' ? input : input.url;
    const method = (init.method || 'GET').toUpperCase();
    const parsed = new URL(url, location.origin);
    const pathname = parsed.pathname;
    const route = serverRoutes.find((r) => r.method === method && r.path.test(pathname));
    const delay = state.dev.loading ? 1400 : 120 + Math.random() * 220;

    return new Promise((resolve) => setTimeout(() => {
      if (state.dev.error || parsed.searchParams.get('fail')) {
        resolve(json({ error: 'server_error' }, 500));
        return;
      }
      if (!route) { resolve(json({ error: 'not_found' }, 404)); return; }
      const params = (pathname.match(route.path) || []).slice(1);
      let result;
      try {
        result = route.handler({ params, body: parseBody(init), q: parsed.searchParams.get('q') });
      } catch (err) {
        resolve(json({ error: err.message }, 400));
        return;
      }
      resolve(json(result, method === 'GET' ? 200 : 201));
    }, delay));
  }

  /* ==============================================================
     F. PERSISTENCE (localStorage, dev reset available)
     ============================================================== */
  function persist() {
    const d = state.data;
    try {
      localStorage.setItem(LS_KEY, JSON.stringify({
        user: d.user, wallet: d.wallet, stats: d.stats, projects: d.projects,
        tasks: d.tasks, updates: d.updates, messages: d.messages, invoices: d.invoices,
        lang: state.lang
      }));
    } catch (e) { /* storage disabled — mock still works in memory */ }
  }
  function hydrate() {
    try {
      const raw = localStorage.getItem(LS_KEY);
      if (!raw) return;
      const saved = JSON.parse(raw);
      Object.keys(saved).forEach((key) => {
        if (key === 'lang') { state.lang = saved.lang; return; }
        if (saved[key] != null) state.data[key] = saved[key];
      });
    } catch (e) { /* ignore corrupted store */ }
  }

  /* ==============================================================
     G. ROUTING
     ============================================================== */
  function currentRoute() {
    const match = location.hash.match(/^#\/solopreneur\/?([a-z]+)?/i);
    const route = (match && match[1] ? match[1] : 'summary').toLowerCase();
    return SECTIONS.indexOf(route) >= 0 ? route : 'summary';
  }

  async function load(route) {
    const endpoint = {
      summary: '/api/solopreneur/summary',
      account: '/api/solopreneur/account',
      projects: '/api/solopreneur/projects',
      wallet: '/api/solopreneur/wallet',
      updates: '/api/solopreneur/updates',
      messages: '/api/solopreneur/messages'
    }[route];

    state.status[route] = 'loading';
    renderView();

    const res = await mockFetch(endpoint);
    if (!res.ok) {
      state.status[route] = 'error';
      renderView();
      return;
    }
    const payload = await res.json();
    applyPayload(route, payload);
    state.status[route] = 'ready';
    renderView();
    renderShell();
  }

  function applyPayload(route, payload) {
    const d = state.data;
    if (route === 'summary') {
      d.user = payload.user; d.wallet = payload.wallet; d.stats = payload.stats;
      d.projects = payload.projects; d.tasks = payload.tasks; d.updates = payload.updates;
      d.events = payload.events; d.messages = payload.messages;
    } else if (route === 'account') {
      d.user = payload.user;
    } else if (route === 'projects') {
      d.projects = payload.projects;
    } else if (route === 'wallet') {
      d.wallet = payload.wallet; d.invoices = payload.invoices;
    } else if (route === 'updates') {
      d.updates = payload.updates;
    } else if (route === 'messages') {
      d.messages = payload.messages;
    }
  }

  /* ==============================================================
     H. ACTIONS
     ============================================================== */
  function openModal(type, id) {
    state.ui.modal = { type, id };
    renderModal();
  }
  function closeModal() {
    state.ui.modal = null;
    renderModal();
  }
  function toast(message, kind) {
    const box = $('toasts');
    const node = document.createElement('div');
    node.className = 'toast' + (kind === 'error' ? ' toast-error' : '');
    node.setAttribute('role', 'status');
    node.textContent = message;
    box.appendChild(node);
    setTimeout(() => {
      node.classList.add('out');
      setTimeout(() => node.remove(), 240);
    }, 3200);
  }

  function pickReply(text) {
    const s = text.toLowerCase();
    if (/(pay|checkout|shop|store|button)/.test(s)) {
      return 'On it. I will draft the change and a human expert will review it today.';
    }
    if (/(plan|credit|billing|invoice)/.test(s)) {
      return 'You have ' + state.data.wallet.credits + ' credits on the ' + state.data.wallet.plan +
        ' plan. If traffic keeps doubling I would move you to Pro — want me to prepare the switch?';
    }
    if (/(backup|security|update)/.test(s)) {
      return 'Backups run every night and the security scan is clean. I will flag anything that changes.';
    }
    if (/(thanks|thank you|great|perfect)/.test(s)) {
      return 'Anytime. I will drop the summary in your Updates feed.';
    }
    return 'Got it. I have queued that up and will report back in your Updates feed.';
  }

