      const res = await mockFetch('/api/solopreneur/tasks/' + id + '/' + op, { method: 'POST' });
      if (!res.ok) { toast(t('err.desc'), 'error'); return; }
      const payload = await res.json();
      state.data.tasks = payload.tasks;
      state.data.projects = payload.projects;
      state.data.stats = payload.stats;
      persist();
      closeModal();
      renderView();
      toast(op === 'complete' ? t('toast.taskDone') : t('toast.taskReopened'));
