      if (!value) return;
      const res = await mockFetch('/api/solopreneur/messages', {
        method: 'POST', body: JSON.stringify({ text: value })
      });
      if (!res.ok) { toast(t('err.desc'), 'error'); return; }
      const payload = await res.json();
      state.data.messages = payload.messages;
      state.ui.typing = true;
      persist();
      renderView();

      setTimeout(() => {
        state.data.messages.push({
          id: 'm_' + Date.now(), from: 'ai', text: pickReply(value), time: nowTime()
        });
        state.ui.typing = false;
        persist();
        renderView();
