    async createProject(form) {
      const data = Object.fromEntries(new FormData(form));
      if (!String(data.name || '').trim()) {
        state.ui.errors = { name: t('common.required') };
        renderModal();
        return;
      }
      state.ui.errors = {};
      const res = await mockFetch('/api/solopreneur/projects', {
        method: 'POST', body: JSON.stringify({ name: data.name, tasks: data.tasks })
      });
      if (!res.ok) { toast(t('err.desc'), 'error'); return; }
      const payload = await res.json();
      state.data.projects = payload.projects;
      persist();
      closeModal();
      renderView();
      toast(t('toast.created'));
    },

    async saveAccount(form) {
      const data = Object.fromEntries(new FormData(form));
      const errors = {};
      if (!String(data.business || '').trim()) errors.business = t('common.required');
      if (!String(data.owner || '').trim()) errors.owner = t('common.required');
      if (!/^[^@\s]+@[^@\s]+\.[a-z]{2,}$/i.test(String(data.email || ''))) errors.email = t('common.emailInvalid');
      state.ui.errors = errors;
      if (Object.keys(errors).length) {
        renderView();
        toast(t('common.fixErrors'), 'error');
        return;
      }
      const res = await mockFetch('/api/solopreneur/account', {
        method: 'PATCH', body: JSON.stringify(data)
      });
      if (!res.ok) { toast(t('err.desc'), 'error'); return; }
      const payload = await res.json();
      state.data.user = payload.user;
      persist();
      renderView();
      renderShell();
      toast(t('toast.saved'));
    },

    async addCredits(form) {
      const data = Object.fromEntries(new FormData(form));
      const res = await mockFetch('/api/solopreneur/wallet/credits', {
        method: 'POST', body: JSON.stringify({ pack: data.pack })
      });
      if (!res.ok) { toast(t('err.desc'), 'error'); return; }
      const payload = await res.json();
      state.data.wallet = payload.wallet;
      state.data.invoices = payload.invoices;
      persist();
      closeModal();
      renderView();
      toast(t('toast.credits'));
    },

    async changePlan(form) {
      const data = Object.fromEntries(new FormData(form));
      const res = await mockFetch('/api/solopreneur/wallet/plan', {
        method: 'PATCH', body: JSON.stringify({ plan: data.plan })
      });
      if (!res.ok) { toast(t('err.desc'), 'error'); return; }
      const payload = await res.json();
      state.data.wallet = payload.wallet;
      state.data.user = payload.user;
      persist();
      closeModal();
      renderView();
      renderShell();
      toast(t('cp.switched'));
    },

    async markAllRead() {
      const res = await mockFetch('/api/solopreneur/updates/read', { method: 'POST' });
      if (!res.ok) { toast(t('err.desc'), 'error'); return; }
      state.data.updates = (await res.json()).updates;
      persist();
      renderView();
      toast(t('toast.markedRead'));
    },

    toggleNotifications() {
      state.data.user.notifications = !state.data.user.notifications;
      persist();
      renderView();
      toast(t('toast.saved'));
    },

    logout() {
      state.ui.loggedOut = true;
      state.ui.modal = null;
      renderModal();
      renderView();
    },

    signIn() {
      state.ui.loggedOut = false;
      renderView();
      load(state.route);
    },

    reset() {
      try { localStorage.removeItem(LS_KEY); } catch (e) { /* noop */ }
      location.reload();
    }
  };

