    const list = state.data.projects
      .filter((p) => !q || p.name.toLowerCase().indexOf(q) >= 0)
      .slice()
      .sort((a, b) => (sort === 'name' ? a.name.localeCompare(b.name) : b.progress - a.progress));

    if (!list.length) return emptyBlock(t('pr.empty'));

    return list.map((p) => {
      const open = state.ui.openProject === p.id;
      const tasks = state.data.tasks.filter((x) => x.context === p.name);
      return '' +
        '<div class="row-item' + (open ? ' is-open' : '') + '">' +
          '<button class="row-head" type="button" data-action="open-project" data-id="' + esc(p.id) + '" ' +
