  function renderView() {
    const host = $('view');
    if (state.ui.loggedOut) { host.innerHTML = viewLoggedOut(); return; }

    const status = state.status[state.route] || 'idle';
    if (status === 'loading' || status === 'idle') { host.innerHTML = viewSkeleton(); return; }
    if (status === 'error') { host.innerHTML = viewError(state.route); return; }

    const views = {
      summary: viewSummary, account: viewAccount, projects: viewProjects,
      wallet: viewWallet, updates: viewUpdates, messages: viewMessages
    };
    host.innerHTML = views[state.route]();
    scrollThread();
  }

  function scrollThread() {
    const thread = $('thread');
    if (thread) thread.scrollTop = thread.scrollHeight;
