    @media (max-width: 1200px) {
      .layout { grid-template-columns: minmax(0, 1fr); }
      .col-side { position: static; }
      .glance { grid-template-columns: repeat(2, minmax(0, 1fr)); }
    }
    @media (max-width: 980px) {
      .app { grid-template-columns: 1fr; }
      .sidebar {
