    /* ==========================================================
       F. MOCK SERVER (in-script "API")
       ========================================================== */
    function toggleTask(id, op) {
      var d = state.data;
      var task = d.tasks.filter(function (x) { return x.id === id; })[0];
      if (!task) throw new Error('task_not_found');
      task.status = op === 'complete' ? 'done' : 'in_progress';
      var project = d.projects.filter(function (p) { return p.name === task.context; })[0];
      if (project) {
        project.progress = Math.max(0, Math.min(100, project.progress + (op === 'complete' ? 3 : -3)));
      }
      d.stats.tasks = Math.max(0, d.stats.tasks + (op === 'complete' ? 1 : -1));
      return { tasks: d.tasks, projects: d.projects, stats: d.stats };
    }

    var ROUTES = {
      'GET /api/solopreneur/summary': function () {
        var d = state.data;
        return {
          user: d.user, wallet: d.wallet, stats: d.stats,
          projects: maybe(d.projects), tasks: maybe(d.tasks), updates: maybe(d.updates),
          events: maybe(d.events), messages: maybe(d.messages)
        };
      },
      'GET /api/solopreneur/account': function () {
        return { user: state.data.user };
      },
      'PATCH /api/solopreneur/account': function (body) {
        ['business', 'owner', 'email', 'country'].forEach(function (k) {
          if (body[k] !== undefined) state.data.user[k] = String(body[k]);
        });
        return { user: state.data.user };
      },
      'GET /api/solopreneur/projects': function () {
        return { projects: maybe(state.data.projects) };
      },
      'POST /api/solopreneur/projects': function (body) {
        var name = String(body.name || '').trim();
        if (!name) throw new Error('invalid_name');
        var variants = ['g1', 'g2', 'g3'];
        var project = {
          id: 'p_' + Date.now(),
          name: name,
          tasks: Math.max(0, Math.min(50, Number(body.tasks) || 0)),
          progress: 0,
          variant: variants[state.data.projects.length % 3],
          updated: '2026-10-19'
        };
        state.data.projects.unshift(project);
        return { projects: state.data.projects, project: project };
      },
      'GET /api/solopreneur/wallet': function () {
        return { wallet: state.data.wallet, invoices: maybe(state.data.invoices) };
      },
      'POST /api/solopreneur/wallet/credits': function (body) {
        var pack = CREDIT_PACKS.filter(function (p) { return p.id === body.pack; })[0] || CREDIT_PACKS[0];
        state.data.wallet.credits += pack.credits;
        state.data.invoices.unshift({
          id: 'i_' + Date.now(), date: '19 Oct 2026',
          desc: pack.credits + ' cxj credits', amount: pack.price, status: 'Paid'
        });
        return { wallet: state.data.wallet, invoices: state.data.invoices };
      },
      'PATCH /api/solopreneur/wallet/plan': function (body) {
        var plan = PLANS.filter(function (p) { return p.id === body.plan; })[0] || PLANS[0];
        state.data.wallet.plan = plan.name;
        state.data.wallet.invoice = plan.price;
        state.data.user.plan = plan.name;
        return { wallet: state.data.wallet, user: state.data.user };
      },
      'GET /api/solopreneur/updates': function () {
        return { updates: maybe(state.data.updates) };
      },
      'POST /api/solopreneur/updates/read': function () {
        state.data.updates.forEach(function (u) { u.read = true; });
        return { updates: state.data.updates };
      },
      'GET /api/solopreneur/messages': function () {
        return { messages: maybe(state.data.messages) };
      },
      'POST /api/solopreneur/messages': function (body) {
        var text = String(body.text || '').trim();
        if (!text) throw new Error('empty_message');
        state.data.messages.push({ id: 'm_' + Date.now(), from: 'me', text: text, time: nowTime() });
        return { messages: state.data.messages };
      }
    };

    async function request(method, path, body) {
      await sleep(state.dev.slow ? 1500 : 170);
      if (state.dev.fail) throw new Error('server_error');

      var key = method + ' ' + path;
      if (ROUTES[key]) return ROUTES[key](body || {});

      var m = path.match(/^\/api\/solopreneur\/tasks\/([^/]+)\/(complete|reopen)$/);
      if (m && method === 'POST') return toggleTask(m[1], m[2]);

      throw new Error('not_found');
    }

    var ENDPOINTS = {
      summary: '/api/solopreneur/summary',
      account: '/api/solopreneur/account',
      projects: '/api/solopreneur/projects',
      wallet: '/api/solopreneur/wallet',
      updates: '/api/solopreneur/updates',
      messages: '/api/solopreneur/messages'
    };

    /* ==========================================================
       G. LOADING / ROUTING
       ========================================================== */
    function currentRoute() {
      var m = location.hash.match(/^#\/solopreneur\/?([a-z]+)?/i);
      var route = (m && m[1] ? m[1] : 'summary').toLowerCase();
      return SECTIONS.indexOf(route) >= 0 ? route : 'summary';
    }

    function applyPayload(route, payload) {
      var d = state.data;
      if (route === 'summary') {
        d.user = payload.user; d.wallet = payload.wallet; d.stats = payload.stats;
        d.projects = payload.projects; d.tasks = payload.tasks; d.updates = payload.updates;
        d.events = payload.events; d.messages = payload.messages;
      } else if (route === 'account') {
        d.user = payload.user;
      } else if (route === 'projects') {
        d.projects = payload.projects;
      } else if (route === 'wallet') {
        d.wallet = payload.wallet; d.invoices = payload.invoices;
      } else if (route === 'updates') {
        d.updates = payload.updates;
      } else if (route === 'messages') {
        d.messages = payload.messages;
      }
    }

    async function load(route) {
      state.route = route;
      state.status = 'loading';
      renderShell();
      renderView();
      try {
        var payload = await request('GET', ENDPOINTS[route]);
        applyPayload(route, payload);
        state.status = 'ready';
      } catch (err) {
        state.status = 'error';
      }
      renderShell();
      renderView();
    }

