    function projectRowsHTML() {
      var q = (state.ui.projectQuery || '').toLowerCase();
      var sort = state.ui.projectSort || 'progress';

      var list = state.data.projects.filter(function (p) {
        return !q || p.name.toLowerCase().indexOf(q) >= 0;
      }).slice().sort(function (a, b) {
        return sort === 'name' ? a.name.localeCompare(b.name) : b.progress - a.progress;
      });

      if (!list.length) return emptyBlock(t('pr.empty'), 'new-project', t('addProject'));

      return list.map(function (p) {
        var open = state.ui.openProject === p.id;
        var tasks = state.data.tasks.filter(function (x) { return x.context === p.name; });
        return '' +
          '<div class="row-item' + (open ? ' is-open' : '') + '">' +
            '<button class="row-head" type="button" data-action="open-project" data-id="' + esc(p.id) + '" ' +
              'aria-expanded="' + (open ? 'true' : 'false') + '">' +
              '<div style="flex:1;min-width:0">' +
                '<h3>' + esc(p.name) + '</h3>' +
                '<small>' + p.tasks + ' ' + esc(t('pr.tasks')) + ' · ' + esc(p.updated) + '</small>' +
              '</div>' +
              '<div class="bar"><i style="width:' + p.progress + '%"></i></div>' +
              '<span class="pct">' + p.progress + '%</span>' +
            '</button>' +
            (open ? '<div class="row-detail">' +
              (tasks.length
                ? '<ul class="tasks">' + tasks.map(taskItem).join('') + '</ul>'
                : '<p class="card-desc" style="margin:0">' + esc(t('pr.noTasks')) + '</p>') +
              '</div>' : '') +
          '</div>';
      }).join('');
    }

