    var VIEWS = {
      summary: viewSummary,
      account: viewAccount,
      projects: viewProjects,
      wallet: viewWallet,
      updates: viewUpdates,
      messages: viewMessages
    };

    function renderView() {
      var host = byId('view');
      if (state.ui.loggedOut) { host.innerHTML = viewLoggedOut(); return; }
      if (state.status === 'loading') { host.innerHTML = viewSkeleton(); return; }
      if (state.status === 'error') { host.innerHTML = viewError(); return; }
      host.innerHTML = VIEWS[state.route]();
      scrollThread();
    }

    function render() {
      renderShell();
      renderView();
      renderModal();
    }

    function scrollThread() {
      var thread = byId('thread');
      if (thread) thread.scrollTop = thread.scrollHeight;
    }
    function focusComposer() {
      var input = byId('composer-input');
      if (input) input.focus();
    }

