            esc(t('common.close')) + '</button>' +
        '</div>';
    }

    var MODALS = {
      newProject: modalNewProject,
      credits: modalCredits,
      plan: modalPlan,
      logout: modalLogout,
      task: function (id) { return modalTask(id); },
      event: function (id) { return modalEvent(id); }
    };

    function renderModal() {
      var root = byId('modal-root');
      var modal = state.ui.modal;
      if (!modal || !MODALS[modal.type]) {
        if (!root.innerHTML) return;
        root.innerHTML = '';
        document.body.style.overflow = '';
        return;
      }
      root.innerHTML =
        '<div class="backdrop" data-action="close-modal"></div>' +
        '<div class="dialog" role="dialog" aria-modal="true" aria-labelledby="dialog-title">' +
          MODALS[modal.type](modal.id) +
        '</div>';
      document.body.style.overflow = 'hidden';
      var focusTarget = root.querySelector('input, select, textarea, button');
      if (focusTarget) focusTarget.focus();
    }

    function openModal(type, id) {
      state.ui.modal = { type: type, id: id };
      renderModal();
    }
    function closeModal() {
      state.ui.modal = null;
      state.ui.errors = {};
      renderModal();
    }

    /* ==========================================================
       L. ACTIONS
       ========================================================== */
    function toast(message, kind) {
      var box = byId('toasts');
      var node = document.createElement('div');
      node.className = 'toast' + (kind === 'error' ? ' toast-error' : '');
      node.setAttribute('role', 'status');
      node.textContent = message;
      box.appendChild(node);
      setTimeout(function () {
        node.classList.add('out');
        setTimeout(function () { node.remove(); }, 240);
      }, 3000);
    }

    function pickReply(text) {
      var s = text.toLowerCase();
      if (/(pay|checkout|shop|store|button)/.test(s)) {
        return 'On it. I will draft the change and a human expert will review it today.';
      }
      if (/(plan|credit|billing|invoice)/.test(s)) {
        return 'You have ' + state.data.wallet.credits + ' credits on the ' +
          state.data.wallet.plan + ' plan. Want me to prepare the switch to Pro?';
      }
      if (/(backup|security|update)/.test(s)) {
        return 'Backups run every night and the security scan is clean. I will flag anything that changes.';
      }
      return 'Got it. I have queued that up and will report back in your Updates feed.';
    }

    var actions = {
      createProject: async function (data) {
        var name = String(data.name || '').trim();
        if (!name) {
          state.ui.errors = { name: t('common.required') };
          renderModal();
          return;
        }
        state.ui.errors = {};
        try {
          var res = await request('POST', '/api/solopreneur/projects', { name: name, tasks: data.tasks });
          state.data.projects = res.projects;
          closeModal();
          render();
          toast(t('toast.created'));
        } catch (err) {
          toast(t('err.desc'), 'error');
        }
      },

      saveAccount: async function (data) {
        var errors = {};
        if (!String(data.business || '').trim()) errors.business = t('common.required');
        if (!String(data.owner || '').trim()) errors.owner = t('common.required');
        if (!/^[^@\s]+@[^@\s]+\.[a-z]{2,}$/i.test(String(data.email || ''))) {
          errors.email = t('common.emailInvalid');
        }
        state.ui.errors = errors;
        if (Object.keys(errors).length) {
          renderView();
          toast(t('common.fixErrors'), 'error');
          return;
        }
        try {
          var res = await request('PATCH', '/api/solopreneur/account', data);
          state.data.user = res.user;
          render();
          toast(t('toast.saved'));
        } catch (err) {
          toast(t('err.desc'), 'error');
        }
      },

      addCredits: async function (data) {
        try {
          var res = await request('POST', '/api/solopreneur/wallet/credits', { pack: data.pack });
          state.data.wallet = res.wallet;
          state.data.invoices = res.invoices;
          closeModal();
          render();
          toast(t('toast.credits'));
        } catch (err) {
          toast(t('err.desc'), 'error');
        }
      },

      changePlan: async function (data) {
        try {
          var res = await request('PATCH', '/api/solopreneur/wallet/plan', { plan: data.plan });
          state.data.wallet = res.wallet;
          state.data.user = res.user;
          closeModal();
          render();
          toast(t('toast.plan'));
        } catch (err) {
          toast(t('err.desc'), 'error');
        }
      },

      markAllRead: async function () {
        try {
          var res = await request('POST', '/api/solopreneur/updates/read');
          state.data.updates = res.updates;
          renderView();
          toast(t('toast.markedRead'));
        } catch (err) {
          toast(t('err.desc'), 'error');
        }
      },

      sendMessage: async function (text) {
        var value = String(text || '').trim();
        if (!value) return;
        try {
          var res = await request('POST', '/api/solopreneur/messages', { text: value });
          state.data.messages = res.messages;
          state.ui.typing = true;
          renderView();
        } catch (err) {
          toast(t('err.desc'), 'error');
          return;
        }
        setTimeout(function () {
          state.data.messages.push({
            id: 'm_' + Date.now(), from: 'ai', text: pickReply(value), time: nowTime()
          });
          state.ui.typing = false;
          if (state.route === 'summary' || state.route === 'messages') renderView();
          focusComposer();
        }, 1100);
      },

      toggleTask: async function (id, op) {
        try {
          var res = await request('POST', '/api/solopreneur/tasks/' + id + '/' + op);
          state.data.tasks = res.tasks;
          state.data.projects = res.projects;
          state.data.stats = res.stats;
          closeModal();
          render();
          toast(op === 'complete' ? t('toast.taskDone') : t('toast.taskReopened'));
        } catch (err) {
          toast(t('err.desc'), 'error');
        }
      },

      toggleNotifications: function () {
        state.data.user.notifications = !state.data.user.notifications;
        renderView();
        toast(t('toast.saved'));
      },

      logout: function () {
        state.ui.loggedOut = true;
        closeModal();
        renderView();
      },

      signIn: function () {
        state.ui.loggedOut = false;
        load(state.route);
      },

      reset: function () {
        state.data = seed();
        state.ui.errors = {};
        state.ui.modal = null;
        state.ui.typing = false;
        state.ui.loggedOut = false;
        state.ui.updatesFilter = 'all';
        state.ui.projectQuery = '';
        state.ui.openProject = null;
        render();
        toast(t('toast.reset'));
      }
    };

    /* ==========================================================
       M. SEARCH
       ========================================================== */
    function searchResults(needle) {
      var q = String(needle || '').trim().toLowerCase();
      if (!q) return [];
      var out = [];
      state.data.projects.forEach(function (p) {
        if (p.name.toLowerCase().indexOf(q) >= 0) out.push({ label: p.name, meta: 'Project', route: 'projects' });
      });
      state.data.tasks.forEach(function (x) {
        if (x.title.toLowerCase().indexOf(q) >= 0) out.push({ label: x.title, meta: 'Task', route: 'summary' });
      });
      state.data.updates.forEach(function (u) {
        if ((u.title + ' ' + u.text).toLowerCase().indexOf(q) >= 0) {
          out.push({ label: u.title, meta: 'Update', route: 'updates' });
        }
      });
      state.data.events.forEach(function (e) {
        if (e.title.toLowerCase().indexOf(q) >= 0) out.push({ label: e.title, meta: 'Calendar', route: 'summary' });
      });
      return out.slice(0, 6);
    }

    function renderSearchResults() {
      var box = byId('search-results');
      if (!box) return;
      var q = state.ui.query;
      if (!q.trim()) { box.hidden = true; box.innerHTML = ''; return; }
      var results = searchResults(q);
      box.innerHTML = results.length
        ? results.map(function (r) {
            return '<button type="button" data-action="goto" data-route="' + r.route + '">' +
              esc(r.label) + '<small>' + esc(r.meta) + '</small></button>';
          }).join('')
        : '<div class="none">No results for “' + esc(q) + '”</div>';
      box.hidden = false;
    }

    /* ==========================================================
       N. EVENTS
       ========================================================== */
    document.addEventListener('click', function (e) {
      var actionEl = e.target.closest('[data-action]');

      if (!e.target.closest('.lang')) {
        var menu = byId('lang-menu');
        if (menu) menu.hidden = true;
      }
      if (!e.target.closest('.search')) {
        var results = byId('search-results');
        if (results) results.hidden = true;
      }
      if (!actionEl) return;

      var action = actionEl.dataset.action;
      var id = actionEl.dataset.id;

      switch (action) {
        case 'lang-toggle': {
          var m = byId('lang-menu');
          if (m) m.hidden = !m.hidden;
          break;
        }
        case 'set-lang':
          state.lang = actionEl.dataset.lang;
          render();
          toast(t('toast.lang'));
          break;
        case 'goto':
          location.hash = '#/solopreneur/' + actionEl.dataset.route;
          break;
        case 'new-project':
          state.ui.errors = {};
          openModal('newProject');
          break;
        case 'add-credits':
          openModal('credits');
          break;
        case 'change-plan':
          openModal('plan');
          break;
        case 'logout':
          openModal('logout');
          break;
        case 'do-logout':
          actions.logout();
          break;
        case 'reset':
          actions.reset();
          break;
        case 'signin':
          actions.signIn();
          break;
        case 'close-modal':
          closeModal();
          break;
        case 'event':
          openModal('event', id);
          break;
        case 'task':
          openModal('task', id);
          break;
        case 'done-task':
          actions.toggleTask(id, 'complete');
          break;
        case 'reopen-task':
          actions.toggleTask(id, 'reopen');
          break;
        case 'retry':
          load(state.route);
          break;
        case 'mark-read':
          actions.markAllRead();
          break;
        case 'filter-updates':
          state.ui.updatesFilter = actionEl.dataset.value;
          renderView();
          break;
        case 'toggle-notifications':
          actions.toggleNotifications();
          break;
        case 'open-project': {
          if (state.route !== 'projects') {
            state.ui.openProject = id;
            location.hash = '#/solopreneur/projects';
          } else {
            state.ui.openProject = state.ui.openProject === id ? null : id;
            var rows = byId('project-rows');
            if (rows) rows.innerHTML = projectRowsHTML();
          }
          break;
        }
        case 'dev-toggle': {
          var body = byId('dev-body');
          if (body) body.hidden = !body.hidden;
          break;
        }
        default:
          break;
      }
    });

    document.addEventListener('submit', function (e) {
      var form = e.target.closest('form[data-form]');
      if (!form) return;
      e.preventDefault();
      var kind = form.dataset.form;
      var data = {};
      new FormData(form).forEach(function (value, key) { data[key] = value; });

      if (kind === 'chat') {
        var input = form.querySelector('input');
        actions.sendMessage(input ? input.value : '');
        return;
      }
      if (kind === 'new-project') actions.createProject(data);
      if (kind === 'credits') actions.addCredits(data);
      if (kind === 'plan') actions.changePlan(data);
      if (kind === 'account') actions.saveAccount(data);
    });

    document.addEventListener('input', function (e) {
      if (e.target.id === 'search-input') {
        state.ui.query = e.target.value;
        renderSearchResults();
        return;
      }
      if (e.target.id === 'project-search') {
        state.ui.projectQuery = e.target.value;
        var rows = byId('project-rows');
        if (rows) rows.innerHTML = projectRowsHTML();
      }
    });

    document.addEventListener('keydown', function (e) {
      if (e.key === 'Escape') {
        if (state.ui.modal) { closeModal(); return; }
        var menu = byId('lang-menu');
        if (menu) menu.hidden = true;
        var results = byId('search-results');
        if (results) results.hidden = true;
      }
    });

    document.addEventListener('change', function (e) {
      var devBox = e.target.closest('[data-dev]');
      if (devBox) {
        state.dev[devBox.dataset.dev] = devBox.checked;
        load(state.route);
        return;
      }
      if (e.target.id === 'project-sort') {
        state.ui.projectSort = e.target.value;
        var rows = byId('project-rows');
        if (rows) rows.innerHTML = projectRowsHTML();
      }
    });

    window.addEventListener('hashchange', function () {
      state.ui.errors = {};
      load(currentRoute());
    });

    /* ==========================================================
       O. BOOT
       ========================================================== */
    load(currentRoute());
  })();
  </script>
</body>
</html>
